                        continue
                    preview_info = manifest[0]
                    preview_path = ''.join([preview_info['name'], preview_info['extension']])
                    break
                if not preview_path:
                    msg = 'Cloud storage {} does not contain any images'.format(pk)
                    slogger.cloud_storage[pk].info(msg)
                    return HttpResponseBadRequest(msg)
                file_status = storage.get_file_status(preview_path)
                if file_status == CloudStorageStatus.NOT_FOUND:
                    raise FileNotFoundError(errno.ENOENT,
                        "Not found on the cloud storage {}".format(db_storage.display_name), preview_path)
                elif file_status == CloudStorageStatus.FORBIDDEN:
                    raise PermissionError(errno.EACCES,
                        "Access to the file on the '{}' cloud storage is denied".format(db_storage.display_name), preview_path)
                with NamedTemporaryFile() as temp_image:
                    storage.download_file(preview_path, temp_image.name)
                    reader = ImageListReader([temp_image.name])
                    preview = reader.get_preview()
                    preview.save(db_storage.get_preview_path())
            content_type = mimetypes.guess_type(db_storage.get_preview_path())[0]
            return HttpResponse(open(db_storage.get_preview_path(), 'rb').read(), content_type)
        except CloudStorageModel.DoesNotExist:
            message = f"Storage {pk} does not exist"
            slogger.glob.error(message)
            return HttpResponseNotFound(message)
        except PermissionDenied:
            raise
        except Exception as ex:
            storage_status = storage.get_status() if storage else None
            if storage_status == CloudStorageStatus.FORBIDDEN:
                msg = 'The resource {} is no longer available. Access forbidden.'.format(storage.name)
            elif storage_status == CloudStorageStatus.NOT_FOUND:
                msg = 'The resource {} not found. It may have been deleted.'.format(storage.name)
            else:
                msg = str(ex)
            return HttpResponseBadRequest(msg)

async def do_actions(self, *, cog: MixinMeta, user: discord.Member=None, message: discord.Message=None,
                     guild: discord.Guild=None, debug=False):
    if message and not user:
        user = message.author
    guild = guild if guild else user.guild
    channel: discord.Channel = message.channel if message else None
    templates_vars = {}
    await populate_ctx_vars(t_vars=templates_vars,
                            rule=self,
                            cog=cog,
                            guild=guild,
                            message=message,
                            user=user,
                            channel=channel,
                            debug=debug)
    def safe_sub(string):
        if string == discord.Embed.Empty:
            return string
        return Template(string).safe_substitute(templates_vars)
    last_sent_message: Optional[discord.Message] = None
    last_expel_action = None
    processors = {}
    def processor(action: Action, suggest: Action=None):
        def decorator(function):
            def wrapper(*args, **kwargs):
                if suggest is not None:
                    cog.send_to_monitor(guild, f"[Warden] ({self.name}): Action "
                                               f"'{action.value}' is deprecated, use "
                                               f"'{suggest.value}' instead.")
                return function(*args, **kwargs)
            processors[action] = wrapper
            return wrapper
        return decorator
    @processor(Action.DeleteUserMessage)
    async def delete_user_message(params: models.IsNone):
        await message.delete()
    @processor(Action.Dm, suggest=Action.SendMessage)
    async def send_dm(params: models.SendMessageToUser):
        nonlocal last_sent_message
        user_to_dm = guild.get_member(params.id)
        if not user_to_dm:
            user_to_dm = discord.utils.get(guild.members, name=params.id)
        if not user_to_dm:
            return
        content = Template(params.content).safe_substitute(templates_vars)
        try:
            last_sent_message = await user_to_dm.send(content)
        except:
            cog.send_to_monitor(guild, f"[Warden] ({self.name}): Failed to DM user "
                                f"{user_to_dm} ({user_to_dm.id})")
            last_sent_message = None
